    @staticmethod
    def _copy(node):
        return Tree(node.label, [Tree._copy(c) for c in node.children])

    def from_pov(self, from_node):
        path = self._copy(self)._path_from_root(from_node)
        if path is None:
            raise ValueError("Tree could not be reoriented")
        # Reverse parent/child links along the path from root to target.
        for parent, child in zip(path, path[1:]):
